package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ReleaseVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property release of observed issue ")
  void test_release_v_o_builder() {
    Assertions.assertFalse(ReleaseVO.nullValue().getRelease().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ReleaseVO.tryFrom(null).getRelease().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ReleaseVO.from("one").getRelease().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ReleaseVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ReleaseVO.from("one").toString());
  }
}
